from construire import Chapter,fig,box,qs,sub
from nouveaux_communs import diagnostic,exercices,bilan,TD7,DS4
from math import pi,sqrt,log10

def create():
 c=Chapter(7,'Filtrage linéaire','1.5','les spectres de signaux périodiques, les fonctions de transfert, les diagrammes de Bode et le choix d’un filtre selon un cahier des charges.')
 c.f('rc-filtre',r'''\draw(0,0)to[V](0,3)to[R,l=$R$](4,3)to[C,l=$C$](4,0)--(0,0);\draw(4,3)--(6,3)node[ocirc]{};\draw(4,0)--(6,0)node[ocirc]{};\draw[-{Stealth},otGreenDark,thick](-.8,.2)--(-.8,2.8)node[midway,left]{$e$};\draw[-{Stealth},otNavy,thick](6.7,.2)--(6.7,2.8)node[midway,right]{$s$};\node[lab,text width=4cm,align=left]at(10,1.5){Sortie non chargée.\\$s=u_C$.\\Passe-bas du premier ordre.};''')
 c.f('cr-filtre',r'''\draw(0,0)to[V](0,3)to[C,l=$C$](4,3)to[R,l=$R$](4,0)--(0,0);\draw(4,3)--(6,3)node[ocirc]{};\draw(4,0)--(6,0)node[ocirc]{};\draw[-{Stealth},otGreenDark,thick](-.8,.2)--(-.8,2.8)node[midway,left]{$e$};\draw[-{Stealth},otNavy,thick](6.7,.2)--(6.7,2.8)node[midway,right]{$s$};\node[lab,text width=4cm,align=left]at(10,1.5){Sortie non chargée.\\$s=u_R$.\\Passe-haut du premier ordre.};''')
 for kind,expr,ymax in [('bas','-10*ln(1+x*x)/ln(10)',3),('haut','20*ln(x)/ln(10)-10*ln(1+x*x)/ln(10)',3)]:
  phase='-atan(x)' if kind=='bas' else '90-atan(x)'
  bounds='ymin=-95,ymax=5,ytick={-90,-45,0}' if kind=='bas' else 'ymin=-5,ymax=95,ytick={0,45,90}'
  c.f('bode-'+kind,rf'''\begin{{groupplot}}[group style={{group size=1 by 2,vertical sep=7mm}},width=13.4cm,height=3.4cm,xmode=log,xmin=.01,xmax=100,grid=both,axis lines=left,tick label style={{font=\small}},label style={{font=\small}}]
\nextgroupplot[ymin=-43,ymax={ymax},ylabel={{$G_{{\rm dB}}$}},xticklabels=\empty]
\addplot[otNavy,thick,domain=.01:100,samples=180]{{{expr}}};\addplot[otMuted,dashed]coordinates{{(.01,-3.0103)(100,-3.0103)}};
\nextgroupplot[{bounds},xlabel={{$\omega/\omega_c$}},ylabel={{$\varphi$ (degrés)}}]
\addplot[otGreenDark,thick,domain=.01:100,samples=180]{{{phase}}};
\end{{groupplot}}''')
 c.f('spectre',r'''\begin{axis}[width=13.4cm,height=5.6cm,xmin=0,xmax=5.5,ymin=0,ymax=3.5,xlabel={$f/f_1$},ylabel={Amplitude (V)},axis lines=left,xtick={0,1,2,3,4,5},grid=major,legend style={draw=none,at={(.98,.98)},anchor=north east,font=\small}]\addplot+[ycomb,otNavy,mark=*,thick]coordinates{(0,1)(1,3)(3,1)(5,.6)};\addlegendentry{Entrée}\addplot+[ycomb,otGreenDark,mark=square*,thick]coordinates{(.06,1)(1.06,2.1213)(3.06,.3162)(5.06,.1177)};\addlegendentry{Sortie}\end{axis}''')
 c.f('cascade',r'''\node[draw=otNavy,fill=otNavyTint,minimum width=3cm,minimum height=1.3cm](a)at(3,0){$H_1$};\node[draw=otNavy,fill=otNavyTint,minimum width=3cm,minimum height=1.3cm](b)at(9,0){$H_2$};\draw[-{Stealth},thick](0,0)--(a)node[midway,above]{$e$};\draw[-{Stealth},thick](a)--(b)node[midway,above]{$u$};\draw[-{Stealth},thick](b)--(12,0)node[midway,above]{$s$};\node[lab,text width=12cm,align=center]at(6,-1.4){$H=H_1H_2$ si le deuxième étage ne modifie pas la réponse du premier.\\Condition pratique : $|Z_{e2}|\gg|Z_{s1}|$ sur la bande utilisée.};''')
 c.intro='Un filtre transforme l’amplitude et la phase de chaque composante d’un signal. L’outil essentiel est la linéarité : connaître la réponse à une sinusoïde permet de reconstruire la réponse à une somme de sinusoïdes. Le calcul d’une fonction de transfert sert donc à prévoir une sortie et à choisir un dispositif.'
 c.mapping='Valeurs moyenne et efficace ; décomposition harmonique fournie ; fonctions de transfert d’ordre 1 et 2 ; Bode du premier ordre ; filtres passe-bas, passe-haut et passe-bande ; moyenneur, intégrateur, dérivateur ; cascade et impédances ; exemple mécanique ; simulation spectrale ; détection de non-linéarités.'
 c.prereq='Chapitre 6 : amplitudes complexes, impédances, gain, phase et résonance. Logarithmes décimaux ; moyenne d’un cosinus ; dérivation et intégration.'
 c.method='Repérer les composantes de l’entrée ; calculer ou lire H pour chacune ; multiplier les amplitudes par le gain et ajouter les phases ; reconstruire la sortie ; vérifier sa moyenne, son spectre et sa valeur efficace.'
 c.boundary='Les séries de Fourier utilisées sont fournies. Le tracé systématique exigible de Bode porte sur l’ordre 1 ; les transferts d’ordre 2 sont exploités et interprétés.'
 diagnostic(c,[(r'Que vaut la moyenne de $\cos\omega t$ sur une période ?',r'Zéro ; l’intégrale de son carré vaut T/2.'),(r'$s=2+3\cos\omega t$ V : quelle moyenne ?',r'2 V. L’amplitude 3 V ne modifie pas la moyenne.'),(r'Convertir un gain 0,1 en décibels.',r'$20\log_{10}(0{,}1)=-20$ dB pour un rapport d’amplitudes.'),(r'Que signifie une décade ?',r'Un rapport 10 de fréquences : par exemple de 100 Hz à 1 kHz.'),(r'Une entrée contient 100 Hz et 300 Hz. Un filtre linéaire stable peut-il créer 200 Hz en régime établi ?',r'Non, pour un système linéaire invariant dans le temps. Une composante initiale transitoire doit être éteinte.'),(r'Que devient C en limite de basse fréquence ?',r'Un circuit ouvert dans le modèle idéal.'),(r'Le module du produit de deux complexes ?',r'Le produit des modules ; l’argument est la somme des arguments modulo $2\pi$.'),(r'Rappeler le transfert RC, sortie C.',r'$H=1/(1+jRC\omega)$ à vide, sous source idéale.')])
 c.c('Décrire un signal périodique',box('loi','Une décomposition fournie',r'\[e(t)=a_0+\sum_{n=1}^{N}A_n\cos(n\omega_1t+\varphi_n).\]$a_0$ est la composante continue ; $f_1=\omega_1/(2\pi)$ la fréquence fondamentale ; $nf_1$ la fréquence de l’harmonique n. Les $A_n$ sont des amplitudes positives, les signes étant absorbés dans les phases.')+sub('Spectre et forme temporelle',r'Un spectre d’amplitude représente des raies à leurs fréquences ; il ne montre pas à lui seul les phases. Deux signaux ayant les mêmes raies peuvent avoir des formes temporelles différentes. Une raie absente a une amplitude nulle ; la fondamentale peut être absente même si la période commune reste définie par les composantes présentes.')+sub('Exemple',r'$e=1+3\cos\omega_1t+\cos(3\omega_1t-\pi/2)$ V a une moyenne de 1 V et deux composantes variables de fréquences $f_1$ et $3f_1$. La période est $1/f_1$. Le spectre à 0 Hz doit être distingué d’une sinusoïde de fréquence très faible.')+box('methode','Lire avant de calculer',r'Faire un tableau : fréquence, amplitude, phase. Conserver ce tableau pour appliquer H à chaque ligne ; traiter la composante continue par H(0).'))
 c.c('Moyenne et valeur efficace',box('loi','Définitions',r'\[\langle s\rangle=\frac1T\int_0^T s(t)\dd t,\qquad S_{\rm eff}=\sqrt{\frac1T\int_0^T s^2(t)\dd t}.\]Pour $s=S_m\cos(\omega t+\varphi)$, l’identité $\cos^2u=(1+\cos2u)/2$ donne $S_{\rm eff}=S_m/\sqrt2$.')+sub('Orthogonalité des harmoniques',r'La moyenne du produit de deux cosinus de fréquences harmoniques distinctes est nulle. Les termes croisés disparaissent donc dans la moyenne du carré :\[S_{\rm eff}^2=a_0^2+\sum_{n=1}^N\frac{A_n^2}{2}.\]La contribution de la composante continue doit être conservée. La valeur efficace ne se calcule pas en additionnant les amplitudes, ni les valeurs efficaces.')+sub('Exemple résolu',r'Pour $s=2+3\cos\omega t+\cos3\omega t$ V, $\langle s\rangle=2$ V et $S_{\rm eff}=\sqrt{4+9/2+1/2}=3$ V. Dans une résistance R, la puissance moyenne est $S_{\rm eff}^2/R$ si s est une tension.')+box('piege','Quel mode du multimètre ?',r'Un mode AC peut supprimer la composante continue. Un appareil donnant une valeur efficace vraie dans sa bande n’a pas le même comportement qu’un appareil étalonné seulement pour des sinusoïdes. Annoncer la grandeur mesurée.'))
 c.c('La fonction de transfert',box('loi','Un rapport complexe',r'\[H(j\omega)=\frac{\underline S}{\underline E},\quad G(\omega)=|H|,\quad \varphi(\omega)=\arg H.\]Pour un filtre linéaire invariant dans le temps, en régime établi :\[s(t)=H(0)a_0+\sum_n A_nG(n\omega_1)\cos[n\omega_1t+\varphi_n+\varphi(n\omega_1)].\]Pour un système réel, H(0) est réel ; son signe est conservé.')+fig('spectre','Exemple de passe-bas avec $f_c=f_1$. Les raies de sortie sont légèrement décalées horizontalement pour la lisibilité ; leurs fréquences physiques sont inchangées.')+sub('La linéarité est le point central',r'Le filtre agit séparément sur chaque raie. Une sinusoïde seule reste sinusoïdale, à la même fréquence. La sortie d’un signal composé peut changer de forme parce que ses harmoniques sont transmises différemment.'))
 c.c('Passe-bas du premier ordre',fig('rc-filtre','Le condensateur reçoit la tension de sortie. Le modèle suppose une forte impédance de mesure.')+box('loi','Réponse harmonique',r'\[H=\frac1{1+j\omega/\omega_c},\quad \omega_c=\frac1{RC}.\]\[G=\frac1{\sqrt{1+x^2}},\quad\varphi=-\arctan x,\quad x=\omega/\omega_c.\]À x = 1, $G=1/\sqrt2$ et $\varphi=-\pi/4$.')+sub('Comprendre les limites',r'À basse fréquence, le condensateur est ouvert et s suit e : H tend vers 1. À haute fréquence, le condensateur dérive le signal et H tend vers zéro. Le gain continu n’est pas nécessairement 1 pour tous les filtres passe-bas ; ici il vaut 1 parce que le montage est non chargé sous source idéale.')+sub('Exemple',r'R = 10 k$\Omega$ et C = 10 nF donnent $\omega_c=10^4$ rad/s et $f_c=1591{,}55$ Hz. À f = fc, une entrée de 2 V d’amplitude donne 1,414 V en sortie, avec retard d’un huitième de période.'))
 c.c('Bode : lire une échelle logarithmique',box('loi','Gain en décibels',r'\[G_{\rm dB}=20\log_{10}G.\]Pour le passe-bas d’ordre 1 : $G_{\rm dB}=-10\log_{10}(1+x^2)$. À $x\ll1$, l’asymptote vaut 0 dB ; à $x\gg1$, elle vaut $-20\log_{10}x$, pente -20 dB par décade.')+fig('bode-bas','Bode en gain du passe-bas. Le point de coupure est à -3,0103 dB ; -3 dB est la notation usuelle arrondie.')+sub('La phase fait partie du diagramme',r'Elle tend vers 0 à basse fréquence, vaut $-45^\circ$ à la coupure et tend vers $-90^\circ$ à haute fréquence. Sur un tracé, noter les unités de l’axe horizontal : une pulsation ne se lit pas comme une fréquence. Les asymptotes donnent une estimation, pas la valeur exacte près du raccord.')+box('methode','Exploiter une pente',r'Un décalage de deux décades dans la zone de pente -20 dB par décade donne -40 dB supplémentaires, donc un rapport d’amplitudes 0,01.'))
 c.c('Passe-haut et dérivation',fig('cr-filtre','Le même couple R, C devient passe-haut si la sortie est prise sur R.')+box('loi','Transfert et limites',r'\[H=\frac{jx}{1+jx},\quad G=\frac{x}{\sqrt{1+x^2}},\quad\varphi=\frac\pi2-\arctan x.\]À basse fréquence H $\simeq j\omega RC$ : $s\simeq RC\dot e$. À haute fréquence H $\simeq1$. La dérivation exige que toutes les composantes utiles vérifient $\omega RC\ll1$.')+fig('bode-haut','Le passe-haut gagne +20 dB par décade à basse fréquence, puis atteint le plateau de 0 dB.')+box('piege','Une dérivation dans une bande',r'Un créneau contient des harmoniques élevées : le modèle de dérivateur ne peut pas rester valable pour toutes. Les pics observés ont une largeur limitée par la bande du montage et de l’appareil.'))
 c.c('Moyenner et intégrer',sub('Le passe-bas comme moyenneur',r'Pour conserver la composante continue et atténuer toutes les composantes variables, choisir $f_c\ll f_1$. Alors $s\simeq a_0$. Le rapport entre ondulation résiduelle et moyenne dépend aussi des amplitudes des harmoniques ; la seule condition qualitative sur fc ne fixe pas une précision.')+box('loi','Le passe-bas comme intégrateur',r'Si chaque composante variable utile vérifie $\omega RC\gg1$, alors\[H\simeq\frac1{j\omega RC},\qquad s_{\rm variable}\simeq\frac1{RC}\int e_{\rm variable}(t)\dd t.\]La composante continue est transmise avec le gain H(0), elle n’est pas intégrée indéfiniment. L’approximation ne décrit pas le démarrage ni une dérive sans borne.')+sub('Calculer une contrainte',r'Exiger $G(f_1)\leq0{,}01$ pour un passe-bas donne $f_1/f_c\geq\sqrt{9999}$, soit $f_c\leq f_1/99{,}995$. À $f_1=1$ kHz, $f_c\leq10{,}0005$ Hz. Avec C = 1 $\mu\mathrm F$, cela impose $R\geq15{,}915$ k$\Omega$.')+box('methode','Nommer l’usage',r'Un même passe-bas peut lisser une tension avec moyenne non nulle et transformer sa faible ondulation en intégrale approchée. Préciser la composante concernée.'))
 c.c('Filtres du deuxième ordre',box('loi','Deux modèles à exploiter',r'Passe-bas :\[H_{\rm PB}=\frac{K}{1-x^2+jx/Q}.\]Passe-bande :\[H_{\rm BP}=\frac{K}{1+jQ(x-1/x)}.\]Pour K réel positif, le premier transmet le continu et décroît comme $K/x^2$ à haute fréquence. Le second annule les très basses et très hautes fréquences, avec gain K à x = 1.')+sub('Résonance et pentes',r'Le passe-bas peut présenter une bosse si $Q>1/\sqrt2$ ; il décroît asymptotiquement de 40 dB par décade. Le passe-bande a des pentes +20 puis -20 dB par décade et une largeur $\Delta\omega=\omega_0/Q$. Q détermine la sélectivité, pas seulement l’amplitude d’une bosse.')+sub('Choisir selon une tâche',r'Pour conserver une moyenne : passe-bas. Pour supprimer un offset lent tout en gardant une bande plus élevée : passe-haut. Pour isoler une composante autour d’une fréquence connue : passe-bande, avec une bande assez large pour garder les variations utiles. Un pic très aigu peut déformer un signal modulé en rejetant ses fréquences voisines.')+box('docu','Le calcul sert la lecture',r'Le programme demande d’exploiter des transferts d’ordre 2 donnés ou des graphes. Un tracé complet systématique de tous leurs cas ne constitue pas l’objectif de cette partie.'))
 c.c('Cascades et impédances',fig('cascade','Le produit des transferts exige que les conditions de charge restent celles des transferts annoncés.')+sub('Deux cellules RC non isolées',r'Pour deux cellules R, C identiques directement en cascade, la deuxième consomme du courant au nœud de la première. Avec $p=j\omega RC$, la loi des nœuds donne\[H=\frac1{1+3p+p^2}.\]Le produit $(1+p)^{-2}$ correspondrait à deux cellules isolées, par exemple par un suiveur idéal. Les deux expressions ont le même ordre à haute fréquence, mais des gains et phases différents autour de la transition.')+box('methode','Condition pratique',r'La tension livrée par un étage de sortie de Thévenin $Z_s$ à une entrée $Z_e$ est multipliée par $Z_e/(Z_s+Z_e)$. Pour limiter la perturbation, rechercher $|Z_e|\gg|Z_s|$ sur toute la bande utile. Une impédance est complexe et dépend de la fréquence.')+sub('Exemple au raccord',r'À $\omega RC=1$, la cascade isolée a H = $-j/2$, gain 0,50 ; la cascade directe a H = $-j/3$, gain 0,333. Multiplier les transferts à vide surestimerait ici la sortie de 50 %.'))
 c.c('Un filtre peut être mécanique',sub('Masse embarquée sur un support mobile',r'Un bâti a une position y(t), une masse m une position absolue x(t), et le déplacement relatif mesuré est z = x - y. Le ressort et l’amortisseur exercent $-kz-b\dot z$. La loi de Newton donne\[m\ddot z+b\dot z+kz=-m\ddot y.\]Le transfert de déplacement relatif vaut\[\frac{\underline Z}{\underline Y}=\frac{x_f^2}{1-x_f^2+jx_f/Q},\quad x_f=\omega/\omega_0.\]')+box('loi','Deux usages du même dispositif',r'À $\omega\ll\omega_0$, $z\simeq-\ddot y/\omega_0^2$ : le déplacement relatif renseigne sur l’accélération du bâti. À $\omega\gg\omega_0$, $\underline Z/\underline Y\simeq-1$ : la masse reste presque immobile tandis que le bâti se déplace, usage sismométrique dans ce modèle.')+sub('Interpréter le filtre',r'Ce transfert supprime les déplacements très lents du support et transmet les variations rapides avec inversion de signe ; il peut résonner près de sa fréquence propre. La bande utile dépend de la grandeur que l’on souhaite mesurer. Ne pas confondre transfert déplacement-déplacement et transfert accélération-déplacement.')+box('piege','Les unités contrôlent le choix',r'Z/Y est sans dimension ; Z/A a l’unité s². Un même graphe ne représente pas ces deux transferts.'))
 c.c('Repérer une non-linéarité',sub('Ce que conserve un système linéaire',r'Un système linéaire invariant dans le temps ne crée pas de fréquence absente de l’entrée en régime établi. Il peut supprimer des composantes, changer leurs phases et leurs amplitudes ; la déformation temporelle résultante ne prouve donc pas à elle seule une non-linéarité.')+box('loi','Un test simple',r'Si $s=ae+be^2$ et $e=A\cos\omega t$, alors\[s=aA\cos\omega t+\frac{bA^2}{2}[1+\cos2\omega t].\]L’apparition de continu et de 2f à partir d’un sinus pur révèle ici la non-linéarité. La composante harmonique varie comme $A^2$.')+sub('Protocole critique',r'Contrôler d’abord le spectre réel de la source. Attendre la disparition du transitoire. Vérifier la fréquence d’échantillonnage et la fenêtre d’analyse ; une fuite spectrale ou un repliement peut simuler des raies. Refaire avec plusieurs amplitudes et vérifier la proportionnalité de la sortie.')+box('methode','Conclure avec précision',r'Un sinus écrêté donne des harmoniques : une saturation est probable. L’absence de nouvelle raie dans une seule expérience ne prouve pas la linéarité pour toutes les amplitudes et fréquences. La conclusion reste limitée à la plage testée.'))
 title,body=c.course[4]
 c.course[4]=(title,body.replace('Bode en gain du passe-bas.','Bode du passe-bas : gain et phase.'))
 c.tp_title='Filtrer un signal composé'
 c.tp=fig('rc-filtre','Mesurer simultanément e et s, avec les masses au même point.')+sub('Protocole',r'Choisir R = 10 k$\Omega$, C = 100 nF, donc fc = 159,15 Hz. Mesurer d’abord le gain et la phase pour f/fc = 0,1 ; 1 ; 10, avec amplitude d’entrée constante. Puis appliquer un créneau centré et comparer les spectres avant et après filtrage. Garder les mêmes réglages d’analyse pour comparer les raies.')+sub('Exploitation corrigée',r'Les gains attendus aux trois points sont 0,9950 ; 0,7071 ; 0,09950 ; phases $-5{,}71^\circ$, $-45^\circ$, $-84{,}29^\circ$. Pour une composante à 3fc, le gain vaut $1/\sqrt{10}=0{,}3162$. Chaque amplitude de sortie doit être comparée à sa propre raie d’entrée. Le filtre ne change aucune fréquence.')+box('docu','Compte rendu',r'Présenter le montage orienté, les composants mesurés, les limites instrumentales, les deux diagrammes de Bode et un tableau spectral. Si l’entrée possède un offset, utiliser le mode DC pour étudier son passage. Les valeurs annoncées ici sont des prévisions du modèle, pas des mesures réalisées.')
 c.num_title='Reconstruire une sortie à partir du spectre'
 c.num=r'''Le spectre fourni contient une moyenne de 1 V et trois harmoniques. Le code réalise exactement la capacité numérique du programme : simuler l’action du filtre, puis modifier sa coupure.
\begin{verbatim}
import numpy as np
import matplotlib.pyplot as plt
f1 = 100.
t = np.linspace(0, 3/f1, 6001)
n = np.array([1, 3, 5])
A = np.array([3., 1., 0.6])
phi = np.array([0., 0., 0.])
w = 2*np.pi*f1*n
e = 1 + np.sum(A[:,None]*np.cos(
    w[:,None]*t + phi[:,None]), axis=0)
outputs = {}
for fc in (10., 100., 1000.):
    H = 1/(1 + 1j*n*f1/fc)
    s = 1 + np.sum((A*np.abs(H))[:,None]*np.cos(
        w[:,None]*t + (phi+np.angle(H))[:,None]),
        axis=0)
    outputs[fc] = s
    plt.plot(t, s, label=f"fc={fc} Hz")
plt.plot(t, e, color="grey", label="entree")
plt.xlabel("t (s)"); plt.ylabel("tension (V)")
plt.legend(); plt.grid(); plt.tight_layout()
\end{verbatim}
À fc = 100 Hz, les amplitudes de sortie sont 2,1213 ; 0,3162 ; 0,1177 V. La moyenne reste 1 V. À 10 Hz, la sortie s’approche de la moyenne ; à 1000 Hz, elle conserve mieux les détails. Vérifier aussi les phases : un filtrage spectral ne consiste pas seulement à réduire les amplitudes.
'''
 bilan(c,r'$S_{\rm eff}^2=a_0^2+\sum A_n^2/2$. Chaque composante est multipliée par H à sa fréquence. $G_{\rm dB}=20\log_{10}|H|$. Pour RC : $\omega_c=1/(RC)$. Les approximations intégrateur et dérivateur exigent une bande adaptée.',r'Partir du besoin et du spectre, puis choisir la nature et la bande du filtre. Vérifier les impédances lorsqu’on raccorde des étages. Reconstruire les phases et contrôler le signal complet.',r'Multiplier une série temporelle entière par un gain unique ; additionner les valeurs efficaces ; confondre fréquence et rang harmonique ; négliger la composante continue ; multiplier des transferts à vide malgré une charge significative.')
 c.td_titles=['Moyenne et valeur efficace','Fréquences et décibels','Étudier un passe-bas','Étudier un passe-haut','Reconstruire la sortie','Choisir un filtre','Cascades et mécanique','Tester la linéarité']
 exercices(c,[
 ('Une sinusoïde décalée',r'$s=3+4\cos\omega t$ V. Calculer moyenne et valeur efficace.',r'$\langle s\rangle=3$ V. $S_{\rm eff}=\sqrt{9+16/2}=\sqrt{17}=4{,}123$ V. Le terme croisé a une moyenne nulle.'),
 ('Deux harmoniques',r'$s=2\cos\omega t+\cos(3\omega t+\pi/4)$ V. Donner la valeur efficace.',r'Les composantes de fréquences distinctes sont orthogonales : $S_{\rm eff}=\sqrt{2^2/2+1^2/2}=\sqrt{2{,}5}=1{,}581$ V, indépendante ici de la phase relative.'),
 ('Un créneau fourni',r'Un signal vaut +A pendant T/2 puis -A pendant T/2. Utiliser les définitions intégrales pour sa moyenne et sa valeur efficace.',r'Les deux contributions à l’intégrale de s se compensent : moyenne nulle. $s^2=A^2$ presque partout, donc valeur efficace A. La relation $A/\sqrt2$ est réservée à une sinusoïde.'),
 ('Un spectre incomplet',r'Un signal contient uniquement des raies à 200 et 300 Hz, de phases fixes et d’amplitudes non nulles. Donner sa période minimale.',r'Les fréquences sont 2 et 3 fois 100 Hz. La période commune minimale est 10 ms, même si la raie à la fondamentale de 100 Hz est absente. Il faut chercher le plus grand diviseur commun des fréquences.'),
 ('Gains et décibels',r'Convertir G = 2, G = 0,01 et $G_{\rm dB}=-6$ dB.',r'$20\log_{10}2=6{,}0206$ dB ; 0,01 donne -40 dB. À -6 dB, G = $10^{-6/20}=0{,}5012$.'),
 ('Une pente',r'Un gain vaut -10 dB à 1 kHz puis suit une pente de -40 dB par décade. Estimer le gain à 100 kHz.',r'Deux décades donnent -80 dB supplémentaires : total -90 dB. Le gain d’amplitude est $10^{-4{,}5}=3{,}162\times10^{-5}$. La réponse est asymptotique, si la pente annoncée reste valable.'),
 ('Choisir C',r'R = 10 k$\Omega$ et fc = 1,00 kHz pour un RC. Déterminer C.',r'$C=1/(2\pi Rf_c)=15{,}915$ nF. Ne pas utiliser $1/(Rf_c)$ : la coupure en pulsation vaut $1/(RC)$.'),
 ('Une composante à la coupure',r'Un passe-bas RC reçoit $e=4\cos(2\pi f_ct)$ V. Écrire s.',r'$s=2\sqrt2\cos(2\pi f_ct-\pi/4)$ V. Le gain est $1/\sqrt2$ et le retard un huitième de période.'),
 ('Au-dessus de la coupure',r'Pour un passe-bas, calculer gain et phase à f = 10fc. Comparer à l’asymptote intégratrice.',r'$G=1/\sqrt{101}=0{,}09950$ et phase $-84{,}289^\circ$. L’approximation donne G = 0,10 et phase $-90^\circ$. L’erreur relative d’amplitude est environ 0,50 %, mais l’écart de phase reste 5,71°.'),
 ('Une moyenne supprimée',r'Un passe-haut reçoit $e=2+3\cos\omega_ct$ V. Déterminer s en régime établi.',r'H(0) = 0 ; la moyenne disparaît. À la coupure, $H=(1+j)/2$, gain $1/\sqrt2$, phase $+\pi/4$. Donc $s=(3/\sqrt2)\cos(\omega_ct+\pi/4)$ V.'),
 ('Dériver une composante',r'Pour un passe-haut avec $\omega RC=0{,}02$, donner le signal approché si $e=5\cos\omega t$ V.',r'$s\simeq RC\dot e=-0{,}10\sin\omega t=0{,}10\cos(\omega t+\pi/2)$ V. Le module exact est $5(0{,}02)/\sqrt{1+0{,}02^2}=0{,}09998$ V.'),
 ('Retrouver la coupure',r'Un passe-haut présente une phase de $45^\circ$ à 800 Hz. Quel est fc ? Que vaut son gain ?',r'Pour l’ordre 1 canonique, $\varphi=\pi/2-\arctan(f/f_c)$. La phase $\pi/4$ impose f/fc = 1. Donc fc = 800 Hz et G = $1/\sqrt2$.'),
 ('Filtrer trois raies',r'$e=1+2\cos\omega_ct+\cos3\omega_ct$ V entre dans un passe-bas RC. Écrire s et sa valeur efficace.',r'$s=1+\sqrt2\cos(\omega_ct-\pi/4)+(1/\sqrt{10})\cos(3\omega_ct-\arctan3)$ V. $S_{\rm eff}^2=1+2/2+0{,}1/2=2{,}05$ ; $S_{\rm eff}=1{,}432$ V.'),
 ('La phase manquante',r'Deux filtres ont le même module H à toutes les harmoniques utiles, mais des phases différentes. Leurs sorties ont-elles même valeur efficace et même forme ?',r'Même valeur efficace pour le même spectre d’entrée, puisque seuls les carrés des amplitudes interviennent. La forme temporelle peut différer par les phases relatives. Si toutes les phases supplémentaires correspondent à un même retard, la forme est simplement translatée.'),
 ('Éliminer un bruit',r'Une composante à 50 kHz doit être atténuée d’au moins 40 dB par un passe-bas d’ordre 1. Donner fc maximal.',r'$G\leq0{,}01$ impose $(50000/f_c)^2\geq9999$, donc $f_c\leq50000/\sqrt{9999}=500{,}025$ Hz. Vérifier ensuite que les composantes utiles restent transmises.'),
 ('Un moyenneur précis',r'$e=2+\cos(2\pi1000t)$ V. Exiger une amplitude d’ondulation inférieure à 0,02 V. Trouver fc maximal d’un passe-bas.',r'$1/\sqrt{1+(1000/f_c)^2}\leq0{,}02$. Donc $f_c\leq1000/\sqrt{2499}=20{,}004$ Hz. La moyenne de sortie vaut 2 V et la limite porte sur l’amplitude de l’ondulation.'),
 ('Une bande sélective',r'Un passe-bande canonique possède f0 = 2 kHz, Q = 20, K = 3. Donner gain maximal et largeur.',r'Le maximum vaut K = 3, soit 9,542 dB ; $\Delta f=f_0/Q=100$ Hz. Un signal utile s’étendant sur 500 Hz serait fortement déformé par ce choix.'),
 ('Une seconde pente',r'Pour $H=1/(1-x^2+jx/Q)$ avec Q = 0,50, trouver G à x = 1 et la limite à grand x.',r'À x = 1, G = Q = 0,50. À grand x, $H\simeq-1/x^2$, donc G $\simeq1/x^2$, phase tendant vers $-\pi$ et pente -40 dB par décade. Il n’y a pas de bosse de résonance.'),
 ('Deux cellules isolées',r'Deux passe-bas RC identiques sont isolés par un suiveur idéal. À $\omega RC=1$, déterminer le transfert total.',r'$H=(1+j)^{-2}=1/(2j)=-j/2$. Gain 0,50, phase $-\pi/2$. Les gains en décibels s’additionnent : deux fois -3,0103 dB.'),
 ('Deux cellules raccordées',r'Pour deux RC identiques sans suiveur, utiliser $H=1/(1+3p+p^2)$ avec p = jωRC. Calculer H à ωRC = 1 et comparer à E19.',r'$H=1/[1+3j-1]=1/(3j)=-j/3$. Gain 1/3 au lieu de 1/2 ; la phase reste $-\pi/2$ à ce point. La deuxième cellule charge la première.'),
 ('Une masse sur un bâti',r'Le déplacement relatif vérifie $\ddot z+2\dot z+100z=-\ddot y$. Donner ω0 et Q ; interpréter le cas ω très faible.',r'$\omega_0=10$ rad/s et $\omega_0/Q=2$, donc Q = 5. Pour ω très faible, $z\simeq-\ddot y/100$ : la position relative mesure l’accélération du bâti avec le facteur $-0{,}01$ s².'),
 ('Un étage trop chargé',r'Un étage a une sortie résistive 1 k$\Omega$ et l’entrée suivante vaut 9 k$\Omega$. Quel facteur de tension supplémentaire apparaît ?',r'$9/(1+9)=0{,}90$, soit -0,915 dB. Une perte de 10 % peut être significative ; le produit des transferts à vide doit être corrigé par ce facteur si le modèle résistif est valable.'),
 ('Un carré révélateur',r'$s=e+0{,}2e^2/\mathrm V$ avec $e=2\cos\omega t$ V. Donner le spectre de sortie.',r'$s=2\cos\omega t+0{,}4+0{,}4\cos2\omega t$ V. Les nouvelles composantes sont 0 et 2f ; le système est non linéaire. Le coefficient 0,2 par volt assure l’homogénéité.'),
 ('Un test insuffisant',r'Un signal composé est déformé en sortie mais aucune fréquence nouvelle n’apparaît. Peut-on conclure à une non-linéarité ? Proposer un meilleur test.',r'Non : une modification différente des amplitudes et phases suffit à déformer un signal dans un filtre linéaire. Injecter un sinus pur, vérifier le spectre d’entrée, rechercher des harmoniques et faire varier l’amplitude pour tester la proportionnalité, en évitant saturation et artefacts d’acquisition.')])
 c.d('Conserver un signal, rejeter une perturbation',r'Un passe-bas d’ordre 1 doit transmettre une composante utile à 100 Hz avec gain au moins 0,95 et atténuer une perturbation à 10 kHz avec gain au plus 0,02.'+qs(r'Traduire les deux conditions en bornes sur fc. Le choix est-il possible ?',r'Choisir fc = 400 Hz et R = 10 k$\Omega$ ; déterminer C.',r'Pour $e=1+2\cos(2\pi100t)+0{,}5\cos(2\pi10000t)$ V, écrire la sortie et calculer sa valeur efficace.',r'Quelle composante fixe l’ondulation résiduelle ? Pourquoi une sortie proche du signal utile ne constitue-t-elle pas un moyenneur ?'),'1. Isoler fc dans le gain exact. 2. Garder les phases. 3. La valeur efficace contient le continu.',r'À 100 Hz, $f_c\geq100/\sqrt{1/0{,}95^2-1}=304{,}24$ Hz. À 10 kHz, $f_c\leq10000/\sqrt{2499}=200{,}04$ Hz. Les deux bornes sont incompatibles : un premier ordre ne satisfait pas ce cahier des charges. Le choix fc = 400 Hz sert à quantifier l’écart, il ne le résout pas. C = 39,789 nF. La sortie vaut $1+(2/\sqrt{1+0{,}25^2})\cos(2\pi100t-\arctan0{,}25)+(0{,}5/\sqrt{626})\cos(2\pi10000t-\arctan25)$ V. Amplitudes : 1,9403 V et 0,019984 V ; phases -14,036° et -87,709°. $S_{\rm eff}=\sqrt{1+1{,}9403^2/2+0{,}019984^2/2}=1{,}6978$ V. Le gain du bruit vaut 0,03997, supérieur à 0,02 malgré sa faible amplitude initiale. Le signal à 100 Hz est conservé ; la sortie n’est donc pas une moyenne. Un ordre plus élevé ou une autre architecture doit être étudié avec le même cahier des charges.')
 c.d('Retrouver le transfert d’une cascade réelle',r'Deux résistances R sont en série entre l’entrée e et la sortie s. Un condensateur C relie le nœud intermédiaire u à la masse ; un autre C relie la sortie à la masse. La sortie est mesurée à vide.'+qs(r'Écrire les deux lois des nœuds en amplitudes complexes.',r'Éliminer u et établir H en posant p = jωRC.',r'Identifier ω0 et Q dans la forme canonique du deuxième ordre.',r'Comparer le continu, le gain à ωRC = 1 et les hautes fréquences avec deux RC isolés.',r'Pourquoi observe-t-on la même pente finale mais pas la même fréquence de transition ?'),'1. Au nœud de sortie : u = (1+p)s. 2. Au premier nœud : e = (2+p)u-s. 3. Développer avant de remplacer p par jωRC.',r'Les lois sont $(\underline E-\underline U)/R=\underline UjC\omega+(\underline U-\underline S)/R$ et $(\underline U-\underline S)/R=jC\omega\underline S$. La seconde donne U = (1+p)S ; la première donne E = (2+p)U-S. Ainsi E = $(1+3p+p^2)$S et $H=1/(1+3p+p^2)$. Avec x = ωRC, le dénominateur est $1-x^2+3jx$ : $\omega_0=1/(RC)$ et Q = 1/3. À continu, les deux montages ont gain 1. À x = 1, le montage direct a gain 1/3 ; l’isolé a gain 1/2 et Q = 1/2 dans sa forme canonique. À grand x, les deux tendent vers $-1/x^2$. L’ordre fixe la pente finale, mais le coefficient du terme du premier degré règle l’amortissement et la transition. Une pente seule ne permet pas d’identifier tout un transfert.')
 c.d('Un accéléromètre mécanique',r'Le déplacement relatif z d’une masse sur un support vérifie $\ddot z+(\omega_0/Q)\dot z+\omega_0^2z=-a(t)$, où a est l’accélération du support. On choisit Q = $1/\sqrt2$ et ω0 = 1000 rad/s.'+qs(r'Établir le transfert Z/A et sa limite statique.',r'On estime l’accélération par $a_{\rm est}=-\omega_0^2z$. Calculer le rapport complexe entre estimation et accélération.',r'Calculer l’erreur sur le module et la phase à ω = 100 rad/s.',r'Pourquoi un bon accord en amplitude n’assure-t-il pas une bonne reproduction temporelle ?',r'Que devient ce capteur à fréquence très élevée ?'),'1. Le signe moins doit être conservé. 2. L’estimation suit un passe-bas de gain statique 1. 3. Avec ce Q, le module se simplifie.',r'$\underline Z/\underline A=-1/[\omega_0^2-\omega^2+j\omega\omega_0/Q]$. La limite statique est $-1/\omega_0^2=-10^{-6}$ s². Le rapport $\underline A_{\rm est}/\underline A=1/(1-x^2+j\sqrt2x)$. Son module vaut $1/\sqrt{1+x^4}$. À x = 0,1, le gain est 0,999950, soit une erreur relative d’amplitude d’environ $5\times10^{-5}$ ; la phase vaut $-\arctan(\sqrt2\times0{,}1/0{,}99)=-8{,}13^\circ$. La quasi-perfection du module masque un retard mesurable. Pour plusieurs harmoniques, leurs phases différentes peuvent déformer le signal. À grand x, le rapport estimé tend vers zéro comme $1/x^2$ et sa phase vers $-\pi$ ; le capteur ne mesure plus fidèlement l’accélération. Une calibration doit préciser une bande de module et une tolérance de phase.')
 c.dm_title='DM — Extraire une moyenne'
 c.dm=r'Une tension vaut $e=2+3\cos(2\pi1000t)+\cos(2\pi3000t)$ V. On utilise un passe-bas RC avec R = 16 k$\Omega$ et C = 1,0 $\mu\mathrm F$.'+sub('A. Spectre et efficacité — 5 points',qs(r'Donner moyenne, période et valeur efficace de l’entrée. (3)',r'Pourquoi le spectre d’amplitude ne suffit-il pas à tracer tout signal ? (2)'))+sub('B. Sortie — 9 points',qs(r'Établir H et calculer fc. (3)',r'Donner amplitudes et phases des deux composantes variables de sortie. (4)',r'Calculer moyenne et valeur efficace de sortie. (2)'))+sub('C. Cahier des charges — 6 points',qs(r'L’amplitude d’ondulation doit rester sous 0,04 V. Donner une borne supérieure simple à partir des deux amplitudes et conclure. (3)',r'Expliquer ce qu’afficheraient un voltmètre DC, un mode AC idéal et un oscilloscope en couplage DC. (3)'))
 c.dm_sol=sub('A — 5 points',r'Moyenne 2 V ; période 1 ms ; $E_{\rm eff}=\sqrt{4+9/2+1/2}=3$ V (3). Les phases relatives sont nécessaires à la reconstruction temporelle (2).')+sub('B — 9 points',r'$H=1/(1+jRC\omega)$ et fc = 9,9472 Hz (3). À 1000 Hz, x = 100,531, amplitude $3/\sqrt{1+x^2}=0{,}029840$ V, phase -89,430°. À 3000 Hz, amplitude 0,0033157 V, phase -89,810° (4). La moyenne reste 2 V ; $S_{\rm eff}=\sqrt{4+(0{,}029840^2+0{,}0033157^2)/2}=2{,}000113$ V (2).')+sub('C — 6 points',r'L’amplitude absolue de l’ondulation est bornée par la somme des amplitudes, soit 0,033156 V < 0,04 V ; la contrainte est satisfaite sans rechercher le maximum exact (3). Le DC mesure la moyenne 2 V ; le mode AC efficace idéal mesure l’ondulation efficace $\sqrt{(0{,}029840^2+0{,}0033157^2)/2}=0{,}02123$ V. L’oscilloscope DC montre la faible ondulation autour de 2 V (3).')
 c.ds_title='DS — Séparer des composantes'
 c.ds=[sub('A. Un signal à traiter — 5 points',r'$e=1+2\cos(2\pi200t)+\cos(2\pi2000t)$ V.'+qs(r'Donner son spectre, sa période et sa valeur efficace. (3)',r'Quel type de filtre permet de réduire la composante à 2 kHz en gardant 200 Hz ? Quelles données manquent pour choisir sa coupure ? (2)'))+sub('B. Un premier ordre — 9 points',r'On choisit $H=1/(1+jf/f_c)$, fc = 400 Hz.'+qs(r'Justifier les deux asymptotes de Bode et donner gain et phase à fc. (3)',r'Reconstruire s(t), puis calculer sa moyenne et sa valeur efficace. (4)',r'Ce filtre est-il un intégrateur pour la composante à 200 Hz ? (2)')),
 sub('C. Un second ordre donné — 6 points',r'On remplace le filtre par $H_2=1/[1-(f/f_0)^2+j(f/f_0)/Q]$, avec f0 = 400 Hz et $Q=1/\sqrt2$.'+qs(r'Montrer que $|H_2|=1/\sqrt{1+(f/f_0)^4}$. (2)',r'Comparer les gains à 200 Hz et 2 kHz avec le premier ordre. (2)',r'Une raie à 4 kHz apparaît en sortie mais n’existe pas à l’entrée. Donner une conclusion prudente et deux vérifications expérimentales. (2)'))]
 c.ds_sol=[sub('A — 5 points',r'Raies : continu 1 V, 200 Hz amplitude 2 V, 2000 Hz amplitude 1 V. Période 5 ms. $E_{\rm eff}=\sqrt{1+2+0{,}5}=\sqrt{3{,}5}$ V (3). Passe-bas ; il faut préciser les tolérances de transmission à 200 Hz et de rejet à 2 kHz (2).')+sub('B — 9 points',r'À bas f : H tend vers 1, 0 dB. À haut f : H $\simeq f_c/(jf)$, pente -20 dB/décade. À fc : $G=1/\sqrt2$, phase -45° (3). La sortie vaut $1+(2/\sqrt{1{,}25})\cos(2\pi200t-\arctan0{,}5)+(1/\sqrt{26})\cos(2\pi2000t-\arctan5)$ V. Amplitudes 1,7889 et 0,19612 V, phases -26,565° et -78,690°. Moyenne 1 V ; $S_{\rm eff}=\sqrt{1+1{,}6+1/52}=1{,}6184$ V (4). À 200 Hz, f/fc = 0,5 ne vérifie pas la condition de haute fréquence : approximation intégratrice injustifiée (2).'),sub('C — 6 points',r'Le dénominateur au carré vaut $(1-x^2)^2+2x^2=1+x^4$ (2). À x = 0,5, $G_2=4/\sqrt{17}=0{,}97014$, supérieur à 0,89443. À x = 5, $G_2=1/\sqrt{626}=0{,}039968$, inférieur à 0,19612 : meilleur maintien de 200 Hz et meilleur rejet de 2 kHz (2). Une fréquence nouvelle est incompatible avec le modèle linéaire invariant en régime établi. Vérifier le spectre source, la saturation, l’échantillonnage et les transitoires avant de conclure à une non-linéarité du filtre (2).')]
 c.hints='E04 : une fondamentale peut être absente. E13 : filtrer séparément les raies. E15 et E16 : utiliser le gain exact avant une approximation. E20 : le transfert direct n’est pas le produit à vide.'
 c.eval_hints='Pour borner une ondulation, la somme des amplitudes donne une borne sûre. Une valeur efficace utilise les carrés. Pour un cahier des charges, établir chaque inégalité avant de choisir un composant.'
 c.source('TD publié — Deux filtres réels',TD7,'TD7, 2025–2026 : exercice 1 et exercice 8.',r'Traiter le filtre RL sortie bobine, puis la cascade RC directe. Redessiner les ports et les masses.',r'Pour RL : $H=jL\omega/(R+jL\omega)$, passe-haut de coupure R/L. Pour deux RC identiques directement raccordés : $H=1/[1+3jRC\omega-(RC\omega)^2]$. Le second étage modifie le premier ; la simple multiplication à vide échoue.')
 c.source('DS publié — Le signal d’une guitare',DS4,'DS n°4 du 11 décembre 2025, partie I, p. 1–2. Sélection : I.1.1 puis I.1.2 a et b.',r'Lire le plateau de basse fréquence et la pente de haute fréquence. Choisir parmi les quatre transferts proposés et établir les asymptotes, sans reprendre les parties de chimie.',r'Le modèle est un passe-bas d’ordre 2 : fonction 2, $H=H_0/(1-x^2+jx/Q)$. À basse fréquence, $G_{\rm dB}\simeq20\log_{10}H_0$ ; à haute fréquence, $G_{\rm dB}\simeq20\log_{10}H_0-40\log_{10}x$, avec $x=\omega/\omega_0$. À $\omega_0$, $H=-jH_0Q$ : gain $H_0Q$, phase $-\pi/2$. Les valeurs de H0 et Q se déterminent ensuite avec les niveaux du graphe, question c.')
 c.next='Le chapitre 8 étudie un autre effet sur un signal : le retard dû à sa propagation dans l’espace.'
 c.check('efficace-ex13',sqrt(2.05),1.4317821063276353)
 c.check('fc-DM',1/(2*pi*.016),9.94718394324346)
 c.check('contrainte-D1-bas',100/sqrt(1/.95**2-1),304.2434922296653)
 c.check('gain-DS2',1/sqrt(626),.039968038348871575)
 return c
